actions.script:
def serviceFacade = ec.factory.serviceFacade
def knownServices = serviceFacade.getKnownServiceNames()
def matchingServices = []
for (name in knownServices) {
    if (name.startsWith("org.moqui.ai.mcp.")) {
        matchingServices.add(name)
    }
}
ec.logger.info("In load#DynamicTools, matchingServices: " + matchingServices.toString())

StringBuilder sb = new StringBuilder()
sb.append("package org.moqui.ai\n\n")
sb.append("import com.google.adk.tools.Annotations.Schema\n\n")
sb.append("class DynamicMcpTools {\n")

def methodServiceMap = [:]
matchingServices.each { serviceName ->
    def sd = serviceFacade.getServiceDefinition(serviceName)
ec.logger.info("In load#DynamicTools, sd: " + sd.toString())
    if (sd != null) {
        // 🎯 FIX: Extract a clean, short method name (e.g., "add_formfield") 
        // so the method name matches what we want Gemini to see as the tool name
        def parts = serviceName.split("\\.")
        def cleanMethodName = parts[parts.length - 1].replace("#", "_").toLowerCase()

        methodServiceMap[cleanMethodName] = serviceName

        def description = sd.serviceNode.attribute("description") ?: sd.serviceNode.first("description")?.getText() ?: "MCP tool for ${serviceName}"
        def cleanDesc = description.replace('"', '\\"').replace('\n', ' ')

        sb.append("    @Schema(description = \"${cleanDesc}\")\n")
        sb.append("    public Map ${cleanMethodName}(\n")

        def inParams = sd.inParameterNameList
        def paramListStr = []
        inParams.each { paramName ->
            def paramInfo = sd.inParameterInfoMap.get(paramName)
            def paramDesc = paramInfo.parameterNode.attribute("description") ?: paramInfo.parameterNode.first("description")?.getText() ?: paramName
            def paramType = "String"
            if (paramInfo.parmClass != null) {
                paramType = paramInfo.parmClass.simpleName
            }

            def cleanParamDesc = paramDesc.replace('"', '\\"').replace('\n', ' ')
            paramListStr.add("        @Schema(name = \"${paramName}\", description = \"${cleanParamDesc}\") ${paramType} ${paramName}")
        }
        sb.append(paramListStr.join(",\n"))
        sb.append("\n    ) {\n")

        sb.append("        def args = [:]\n")
        inParams.each { paramName ->
            sb.append("        if (${paramName} != null) args.${paramName} = ${paramName}\n")
        }
        sb.append("        return org.moqui.Moqui.getExecutionContext().service.sync().name(\"${serviceName}\").parameters(args).call()\n")
        sb.append("    }\n\n")
    }
}
sb.append("}\n")

ec.logger.info("In load#DynamicTools, sb: " + sb.toString())

ClassLoader parentClassLoader = Thread.currentThread().getContextClassLoader()
GroovyClassLoader gcl = new GroovyClassLoader(parentClassLoader)
Class<?> clazz = gcl.parseClass(sb.toString())
def instance = clazz.getDeclaredConstructor().newInstance()

def toolsList = []
methodServiceMap.keySet().each { cleanMethodName ->
    try {
        // 🎯 FIX: Reverted to the correct two-parameter factory method signature supported by the ADK
        def tool = com.google.adk.tools.FunctionTool.create(instance, cleanMethodName)
        toolsList.add(tool)
    } catch (Exception e) {
        ec.logger.error("Failed to register dynamic tool ${cleanMethodName}: " + e.getMessage(), e)
    }
}
context.toolsList = toolsList

import org.moqui.adk.AdkManager

Map toolMap = [:]

// 1. DIRECT SERVICE INSPECTION FOR org.moqui.ai.mcp.* SERVICES
def serviceFacade = ec.factory.serviceFacade
def knownServices = serviceFacade.getKnownServiceNames()

for (String serviceName in knownServices) {
    if (serviceName.startsWith("org.moqui.ai.mcp.")) {
        def sd = serviceFacade.getServiceDefinition(serviceName)
        if (sd != null) {
            def parts = serviceName.split("\\.")
            def cleanMethodName = parts[parts.length - 1].replace("#", "_").toLowerCase()

            def description = sd.serviceNode.attribute("description") ?: sd.serviceNode.first("description")?.getText() ?: "MCP tool for ${serviceName}"

            // Build Input Schema from Service In-Parameters
            Map propertiesMap = [:]
            List requiredList = []

            sd.inParameterNameList.each { paramName ->
                def paramInfo = sd.inParameterInfoMap.get(paramName)
                if (paramInfo != null) {
                    def paramNode = paramInfo.parameterNode
                    boolean isInternal = paramNode.attribute("internal") == "true" || paramNode.attribute("scope") == "context"
                    def paramDesc = paramInfo.parameterNode.attribute("description") ?: paramInfo.parameterNode.first("description")?.getText() ?: paramName
                    def paramType = "string"
                    if (paramInfo.parmClass != null) {
                        String sName = paramInfo.parmClass.simpleName.toLowerCase()
                        if (sName.contains("int") || sName.contains("long")) paramType = "integer"
                        else if (sName.contains("bool")) paramType = "boolean"
                    }

                    propertiesMap[paramName] = [
                        type: paramType,
                        description: paramDesc,
                        internal: isInternal
                    ]

                    if (paramInfo.parameterNode.attribute("required") == "true") {
                        requiredList.add(paramName)
                    }
                }
            }

            toolMap[cleanMethodName] = [
                name: cleanMethodName,
                serviceName: serviceName, // e.g. "org.moqui.ai.mcp.ScreenServices.create#Screen"
                title: cleanMethodName.replace("_", " ").capitalize(),
                description: description,
                inputSchema: [
                    type: "object",
                    properties: propertiesMap,
                    required: requiredList
                ]
            ]
        }
    }
}

// 2. Query AdkManager active agent for additional built-in tools / toolsets
try {
    def activeAgent = AdkManager.agentRegistry?.get(AdkManager.DEFAULT_CONFIG)

    if (activeAgent != null) {
        def rawToolsObj = activeAgent.tools()
        List resolvedTools = []

        if (rawToolsObj != null) {
            if (rawToolsObj.metaClass.respondsTo(rawToolsObj, "blockingGet")) {
                resolvedTools = rawToolsObj.blockingGet() as List
            } else if (rawToolsObj.metaClass.respondsTo(rawToolsObj, "blockingFirst")) {
                resolvedTools = rawToolsObj.blockingFirst() as List
            } else if (rawToolsObj instanceof List) {
                resolvedTools = rawToolsObj
            }
        }

        resolvedTools.each { tool ->
            try {
                // 🎯 Safe ADK Tool Name Resolution
                String tName = null
                try { tName = tool.getName() } catch (Throwable ignored) { tName = tool.name }

                // If it evaluated to a class string or memory reference, filter it out or sanitize
                if (tName && !tName.startsWith("com.google.adk") && !tName.contains("@")) {
                    if (!toolMap.containsKey(tName)) {
                        String desc = "Agent Tool"
                        try { desc = tool.getDescription() } catch (Throwable ignored) {}

                        toolMap[tName] = [
                            name: tName,
                            title: tName.replace("_", " ").capitalize(),
                            description: desc,
                            inputSchema: [:]
                        ]
                    }
                }
            } catch (Exception te) {}
        }
    }
} catch (Exception ex) {
    ec.logger.warn("⚠️ Error inspecting AdkManager agent tools: " + ex.message)
}

context.tools = new ArrayList(toolMap.values())
